write: {"content": "import csv

def bubble_sort_by_name(rows):
    a = rows[:]
    n = len(a)
    for i in range(n):
        swapped = False
        for j in range(0, n - i - 1):
            if a[j][0] > a[j+1][0]:
                a[j], a[j+1] = a[j+1], a[j]
                swapped = True
        if not swapped:
            break
    return a

def main():
    with open('компоненты.csv', 'r', encoding='utf-8', newline='') as f:
        reader = csv.reader(f, delimiter=';')
        header = next(reader, None)
        rows = [row for row in reader if row]

    sorted_rows = bubble_sort_by_name(rows)

    print(';'.join(header) if header else 'компонент;лицензия;страна правообладателя')
    for r in sorted_rows:
        print(';'.join(r))

if __name__ == '__main__':
    main()
